import React from 'react';
import {
  Box,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Checkbox,
  ListItemText,
  ToggleButtonGroup,
  ToggleButton,
  Paper,
  Grid,
  Button,
  Typography,
  OutlinedInput
} from '@mui/material';
import FilterAltOffIcon from '@mui/icons-material/FilterAltOff';

const ITEM_HEIGHT = 48;
const ITEM_PADDING_TOP = 8;
const MenuProps = {
  PaperProps: {
    style: {
      maxHeight: ITEM_HEIGHT * 4.5 + ITEM_PADDING_TOP,
      width: 250,
    },
  },
};

function AnalyticsFilters({
  years,
  clubs,
  selectedYears,
  selectedClubs,
  venue,
  onChangeYears,
  onChangeClubs,
  onChangeVenue,
  onClearFilters
}) {
  return (
    <Paper elevation={3} sx={{ p: 3, mb: 4, borderRadius: 3, border: '1px solid rgba(255, 255, 255, 0.05)', bgcolor: 'background.paper' }}>
      <Grid container spacing={3} alignItems="center">
        {/* Years Multiselect */}
        <Grid item xs={12} sm={6} md={3.5}>
          <FormControl fullWidth size="small">
            <InputLabel id="analytics-years-label">Filter Years</InputLabel>
            <Select
              labelId="analytics-years-label"
              id="analytics-years-select"
              multiple
              value={selectedYears}
              onChange={(e) => onChangeYears(e.target.value)}
              input={<OutlinedInput label="Filter Years" />}
              renderValue={(selected) => selected.length === 0 ? 'All Years' : selected.join(', ')}
              MenuProps={MenuProps}
            >
              {years.map((year) => (
                <MenuItem key={year} value={year}>
                  <Checkbox checked={selectedYears.includes(year)} color="primary" />
                  <ListItemText primary={year} />
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        {/* Clubs Multiselect */}
        <Grid item xs={12} sm={6} md={3.5}>
          <FormControl fullWidth size="small">
            <InputLabel id="analytics-clubs-label">Filter Clubs</InputLabel>
            <Select
              labelId="analytics-clubs-label"
              id="analytics-clubs-select"
              multiple
              value={selectedClubs}
              onChange={(e) => onChangeClubs(e.target.value)}
              input={<OutlinedInput label="Filter Clubs" />}
              renderValue={(selected) => selected.length === 0 ? 'All Clubs' : selected.join(', ')}
              MenuProps={MenuProps}
            >
              {clubs.map((club) => (
                <MenuItem key={club} value={club}>
                  <Checkbox checked={selectedClubs.includes(club)} color="primary" />
                  <ListItemText primary={club} />
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Grid>

        {/* Location Toggle Group */}
        <Grid item xs={12} sm={6} md={3}>
          <Box sx={{ display: 'flex', flexDirection: 'column', width: '100%' }}>
            <Typography variant="caption" color="text.secondary" sx={{ mb: 0.5, fontWeight: 'bold' }}>
              Venue / Location
            </Typography>
            <ToggleButtonGroup
              color="primary"
              value={venue}
              exclusive
              onChange={(e, val) => val && onChangeVenue(val)}
              aria-label="venue toggle"
              size="small"
              fullWidth
            >
              <ToggleButton value="All">All</ToggleButton>
              <ToggleButton value="Home Only">Home</ToggleButton>
              <ToggleButton value="Away Only">Away</ToggleButton>
            </ToggleButtonGroup>
          </Box>
        </Grid>

        {/* Reset button */}
        <Grid item xs={12} sm={6} md={2}>
          <Button
            variant="outlined"
            color="inherit"
            startIcon={<FilterAltOffIcon />}
            onClick={onClearFilters}
            fullWidth
            size="medium"
            sx={{ borderRadius: 2, textTransform: 'none', border: '1px solid rgba(255, 255, 255, 0.12)' }}
          >
            Clear Filters
          </Button>
        </Grid>
      </Grid>
    </Paper>
  );
}

export default AnalyticsFilters;
